 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The solid-color grid lines partition the canvas into rectangular tiles.
    hr = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != 0]
    vc = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]

    def intervals(n, cuts):
        out, start = [], 0
        for x in cuts:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out

    rows = intervals(h, hr)
    cols = intervals(w, vc)
    for r0, r1 in rows:
        tiles = []
        for c0, c1 in cols:
            cells = [(r, c) for r in range(r0, r1) for c in range(c0, c1) if g[r][c] != 0]
            tiles.append(cells)
        used = set()
        # Existing horizontally mirrored neighbors are already complete.
        for j in range(len(cols) - 1):
            a, b = tiles[j], tiles[j + 1]
            if not a or not b:
                continue
            ar0, ac0 = rows[rows.index((r0, r1))][0], cols[j][0]
            br0, bc0 = r0, cols[j + 1][0]
            ah, aw = r1 - r0, cols[j][1] - cols[j][0]
            bw = cols[j + 1][1] - cols[j + 1][0]
            if aw != bw:
                continue
            pa = {(r-r0, c-ac0, g[r][c]) for r,c in a}
            pb = {(r-r0, c-bc0, g[r][c]) for r,c in b}
            reflected = {(rr, aw-1-cc, color) for rr,cc,color in pa}
            if reflected == pb:
                used.update((j, j+1))
        # A lone object is copied, horizontally reflected, into the empty tile immediately right.
        for j, cells in enumerate(tiles[:-1]):
            if not cells or j in used or tiles[j+1]:
                continue
            c0, c1 = cols[j]
            d0, d1 = cols[j+1]
            if c1-c0 != d1-d0:
                continue
            for r,c in cells:
                g[r][d0 + (c1-1-c)] = g[r][c]
    return g
"
