    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Identify the grid's full-color divider rows and columns.
    hr = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != 0]
    vc = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]
    def spans(n, cuts):
        out, start = [], 0
        for x in cuts:
            if start < x: out.append((start, x))
            start = x + 1
        if start < n: out.append((start, n))
        return out
    rows, cols = spans(h, hr), spans(w, vc)
    # Each row of cells is made left-right symmetric about the grid center.
    for r0, r1 in rows:
        for j in range(len(cols)//2):
            k = len(cols)-1-j
            a0,a1 = cols[j]; b0,b1 = cols[k]
            if a1-a0 != b1-b0: continue
            a = [(r,c,g[r][c]) for r in range(r0,r1) for c in range(a0,a1) if g[r][c] not in (0,)]
            b = [(r,c,g[r][c]) for r in range(r0,r1) for c in range(b0,b1) if g[r][c] not in (0,)]
            if a and not b:
                for r,c,v in a: g[r][b0+(a1-1-c)] = v
            elif b and not a:
                for r,c,v in b: g[r][a0+(b1-1-c)] = v
    return g
