    def spans(n, cuts):
        out=[]; s=0
        for x in cuts:
            if s<x: out.append((s,x))
            s=x+1
        if s<n: out.append((s,n))
        return out
    rs, cs = spans(h,hr), spans(w,vc)
    for r0,r1 in rs:
        # Snapshot all tile contents before adding reflected copies.
        contents=[]
        for c0,c1 in cs:
            contents.append({(r-r0,c-c0):g[r][c] for r in range(r0,r1) for c in range(c0,c1) if g[r][c] != 0})
        paired=set()
        for j in range(len(cs)-1):
            a,b=contents[j],contents[j+1]
            aw=cs[j][1]-cs[j][0]; bw=cs[j+1][1]-cs[j+1][0]
            if aw==bw and a and b and {(r,aw-1-c):v for (r,c),v in a.items()}==b:
                paired.update((j,j+1))
        additions=[]
        for j,shape in enumerate(contents):
            if not shape or j in paired: continue
            candidates=[k for k in (j-1,j+1) if 0<=k<len(cs) and not contents[k]]
            if not candidates: continue
            # Prefer inward; if that reflected copy collides with an already planned
            # reflected object, use the other empty neighbor instead.
            center=(len(cs)-1)/2
            candidates.sort(key=lambda k:(abs(k-center),abs(k-j)))
            selected=None
            for k in candidates:
                a0,a1=cs[j]; b0,b1=cs[k]
                if a1-a0 != b1-b0: continue
                dest={(r, b0+(a1-1-(a0+c)),v) for (r,c),v in []} # empty placeholder
                points={(r0+rr, b0+(a1-1-(a0+cc)),v) for (rr,cc),v in shape.items()}
                occupied={(r,c,g[r][c]) for r in range(r0,r1) for c in range(b0,b1) if g[r][c]!=0}
                # Avoid overwriting a different colored figure.
                if any(g[r][c] not in (0,v) for r,c,v in points): continue
                selected=(k,points); break
            if selected: additions.append(selected[1])
        for points in additions:
            for r,c,v in points: g[r][c]=v
    return g
