    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Full-color lines divide the grid into cell rows and cell columns.
    hr = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != 0]
    vc = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]

    def spans(n, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    row_spans = spans(h, hr)
    col_spans = spans(w, vc)
    # Each neighboring pair of cells forms a horizontally reflected pair.
    for r0, r1 in row_spans:
        for left in range(0, len(col_spans) - 1, 2):
            right = left + 1
            l0, l1 = col_spans[left]
            rcol0, rcol1 = col_spans[right]
            if l1 - l0 != rcol1 - rcol0:
                continue
            left_obj = {(r-r0, c-l0): g[r][c]
                        for r in range(r0, r1) for c in range(l0, l1) if g[r][c] != 0}
            right_obj = {(r-r0, c-rcol0): g[r][c]
                         for r in range(r0, r1) for c in range(rcol0, rcol1) if g[r][c] != 0}
            if left_obj and not right_obj:
                for (rr, cc), color in left_obj.items():
                    g[r0+rr][rcol0 + (rcol1-rcol0-1-cc)] = color
            elif right_obj and not left_obj:
                for (rr, cc), color in right_obj.items():
                    g[r0+rr][l0 + (l1-l0-1-cc)] = color
    return g
