    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    hr = [r for r in range(h) if len(set(out[r])) == 1 and out[r][0] != 0]
    vc = [c for c in range(w) if len({out[r][c] for r in range(h)}) == 1 and out[0][c] != 0]
    def spans(n, cuts):
        ans=[]; start=0
        for x in cuts:
